/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Harness
 *   Functions: getPath, matchesValue, setPath, harness, tokenFor, upload, rejectsWith
 *   Constants: trackId, videoKey, nextVideoKey, file
 * Tests
 *   - a first upload records exact evidence and promotes a preview bound to the active Video
 *   - storage metadata names the MediaTrack provenance, and the uploader is never provenance
 *   - a replacement keeps the old preview public until promotion, then deletes its exact version
 *   - an upload for a different source, a stale revision, or an ineligible track writes nothing
 *   - a failed replacement keeps the first preview active and public
 *   - a definite storage refusal clears the reservation, and an unknown outcome stays reconcilable
 *   - an unknown outcome whose PUT actually landed is deleted by the version HEAD returns
 *   - a live upload lease blocks another upload and its recovery
 *   - a source replaced during upload abandons the preview and deletes its own exact object
 *   - a missing strong ETag abandons the upload instead of publishing an unverifiable preview
 *   - a failed old-preview delete keeps the new preview public and blocks the next upload until it drains
 *   - retiring a preview made for a replaced Video deletes it, never throws, and leaves deletion alone
 *   - removing a preview deletes its exact version and requires the current revision
 *   - status reports eligibility and a source token without exposing storage keys or versions
 *   - stale, mismatched, or ineligible requests are refused before the decode runs
 *   - a promote whose acknowledgement is lost is confirmed by its fence and never deleted while it may be live
 *   - a committed upload or removal reports a failed cleanup read as pending, never as a failure
 *   - once MediaTrack deletion begins, preview work refuses, and a racing write leaves its fence untouched
 *   - a bucket without versioning resolves an unknown outcome as the exact null version
 *   - recovery fences the pending record before deleting, so a failed delete retries by exact version
 *   - every guarded preview write misses once deletion has begun, even after a stale read
 *   - an upload that fails before promotion deletes its own object even when its record changed
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';

import {
    MotionPreviewLifecycleError,
    motionPreviewSourceToken,
    motionPreviewStatus,
    reconcileMotionPreview,
    removeMotionPreview,
    retireStaleMotionPreview,
    uploadMotionPreview,
    type MotionPreviewLifecycleDependencies
} from '../../src/services/media/motionPreviewLifecycleService';
import { publicMotionPreviewForTrack } from '../../src/services/media/motionPreviewService';

const trackId = '64b000000000000000000001';
const videoKey = `video/${trackId}/64b0000000000000000000aa`;
const nextVideoKey = `video/${trackId}/64b0000000000000000000bb`;

const getPath = (value: any, path: string) => path.split('.').reduce((current, key) => (
    current == null ? undefined : current[key]
), value);

/** Matches one filter value: equality, null for missing, or the `$nin` operator the lifecycle uses. */
const matchesValue = (actual: unknown, expected: unknown) => {
    if (expected === null) return actual == null;
    if (expected && typeof expected === 'object' && '$nin' in expected) {
        return !(expected as { $nin: unknown[] }).$nin.includes(actual);
    }
    return actual === expected;
};

const setPath = (value: any, path: string, next: unknown) => {
    const parts = path.split('.');
    let current = value;
    for (const part of parts.slice(0, -1)) {
        if (current[part] == null || typeof current[part] !== 'object') current[part] = {};
        current = current[part];
    }
    current[parts.at(-1)!] = next === undefined ? undefined : structuredClone(next);
};

interface Harness {
    state: any;
    objects: Map<string, { versionId: string; etag: string; metadata: Record<string, string> }>;
    deleted: Array<{ key: string; versionId: string | null }>;
    puts: string[];
    deps: Partial<MotionPreviewLifecycleDependencies>;
    keys: string[];
}

/** A Mongo-like single-document store and a versioned S3 fake behind the lifecycle boundaries. */
const harness = (initial: Record<string, unknown> = {}): Harness => {
    let keyCounter = 0;
    let versionCounter = 0;
    let now = new Date('2026-10-18T00:00:00Z').getTime();
    const keys: string[] = [];
    const h: Harness = {
        state: { _id: trackId, uploadStatus: 'ready', mediaType: 'video', s3Key: videoKey, pendingS3Key: null, ...initial },
        objects: new Map(),
        deleted: [],
        puts: [],
        keys,
        deps: {}
    };
    h.deps = {
        findTrack: async () => structuredClone(h.state),
        updateTrackWhere: async (_id, expected, update) => {
            const matches = Object.entries(expected).every(([path, value]) => matchesValue(getPath(h.state, path), value));
            if (!matches) return { matchedCount: 0 };
            for (const [path, value] of Object.entries(update)) setPath(h.state, path, value);
            return { matchedCount: 1 };
        },
        putObject: async (key, _file, metadata) => {
            h.puts.push(key);
            const versionId = `v${++versionCounter}`;
            const etag = `"etag-${versionCounter}"`;
            h.objects.set(key, { versionId, etag, metadata });
            return { ETag: etag, VersionId: versionId };
        },
        headObject: async (key) => {
            const object = h.objects.get(key);
            return object ? { ETag: object.etag, VersionId: object.versionId, Metadata: object.metadata } : null;
        },
        deleteObject: async (key, versionId) => {
            h.deleted.push({ key, versionId });
            const object = h.objects.get(key);
            if (object && (versionId === null || object.versionId === versionId)) h.objects.delete(key);
        },
        createObjectKey: () => {
            const key = `motion-preview/${trackId}/${String(++keyCounter).padStart(24, 'c')}`;
            keys.push(key);
            return key;
        },
        validate: async () => ({
            durationMs: 6_000, width: 854, height: 480, byteLength: 900_000, sha256: 'a'.repeat(64)
        }),
        now: () => new Date(now),
        randomRevision: () => `pv_${String(keyCounter).padStart(32, '0')}`
    };
    (h as any).advance = (ms: number) => { now += ms; };
    return h;
};

const file = { size: 900_000, mimetype: 'video/mp4', buffer: Buffer.alloc(1) } as Express.Multer.File;
const tokenFor = (key = videoKey) => motionPreviewSourceToken(trackId, key);

const upload = (h: Harness, expectedRevision: number, overrides: Partial<MotionPreviewLifecycleDependencies> = {}) => (
    uploadMotionPreview({
        actorId: 'admin-1', mediaTrackId: trackId, file, sourceToken: tokenFor(), expectedRevision
    }, { ...h.deps, ...overrides })
);

const rejectsWith = async (promise: Promise<unknown>, status: number, code: string) => {
    await assert.rejects(promise, (error: unknown) => {
        assert.ok(error instanceof MotionPreviewLifecycleError);
        assert.equal(error.statusCode, status);
        assert.equal(error.code, code);
        return true;
    });
};

test('a first upload records exact evidence and promotes a preview bound to the active Video', async () => {
    const h = harness();
    const result = await upload(h, 0);

    const active = h.state.motionPreview.active;
    assert.equal(active.status, 'ready');
    assert.equal(active.s3Key, h.keys[0]);
    assert.equal(active.versionId, 'v1');
    assert.equal(active.etag, '"etag-1"');
    assert.deepEqual(active.source, { s3Key: videoKey });
    assert.equal(active.updatedBy, 'admin-1');
    assert.equal(h.state.motionPreview.pending, null);
    assert.equal(h.state.motionPreview.cleanup, null);
    assert.equal(result.cleanupPending, false);
    assert.match(result.revision, /^pv_[0-9a-f]{32}$/);
    assert.equal(h.objects.get(h.keys[0])?.metadata.trackid, trackId);
    assert.equal(h.objects.get(h.keys[0])?.metadata.ownerid, 'admin-1');
});

test('storage metadata names the MediaTrack provenance, and the uploader is never provenance', async () => {
    const h = harness({ createdBy: 'curator-1' });
    await upload(h, 0);

    assert.equal(h.objects.get(h.keys[0])?.metadata.ownerid, 'curator-1');
    assert.equal(h.state.motionPreview.active.updatedBy, 'admin-1');
    assert.equal('createdBy' in h.state.motionPreview.active, false);
});

test('a replacement keeps the old preview public until promotion, then deletes its exact version', async () => {
    const h = harness();
    await upload(h, 0);
    const first = h.state.motionPreview.active;
    const enabled = { FINITUDE_MOTION_PREVIEWS_ENABLED: 'true' };

    let checkedInFlight = false;
    await upload(h, h.state.motionPreview.revision, {
        putObject: async (key, received, metadata) => {
            // While the replacement is being written, listeners still see the first preview.
            assert.equal(h.state.motionPreview.active.s3Key, first.s3Key);
            assert.equal(publicMotionPreviewForTrack(h.state, enabled)?.s3Key, first.s3Key);
            checkedInFlight = true;
            return h.deps.putObject!(key, received, metadata);
        }
    });
    assert.equal(checkedInFlight, true);

    assert.equal(h.state.motionPreview.active.s3Key, h.keys[1]);
    assert.equal(h.state.motionPreview.cleanup, null);
    assert.deepEqual(h.deleted, [{ key: first.s3Key, versionId: first.versionId }]);
    assert.equal(h.objects.has(first.s3Key), false);
});

test('an upload for a different source, a stale revision, or an ineligible track writes nothing', async () => {
    const h = harness();
    await rejectsWith(uploadMotionPreview({
        actorId: 'admin-1', mediaTrackId: trackId, file, sourceToken: tokenFor(nextVideoKey), expectedRevision: 0
    }, h.deps), 409, 'ADMIN_MOTION_PREVIEW_SOURCE_CHANGED');
    await rejectsWith(upload(h, 7), 409, 'ADMIN_MOTION_PREVIEW_STALE_REVISION');
    for (const changes of [{ mediaType: 'audio', s3Key: `audio/${trackId}/64b0000000000000000000cc` }, { mediaType: undefined }, { uploadStatus: 'deleting' }]) {
        const ineligible = harness(changes);
        await rejectsWith(upload(ineligible, 0), 409, 'ADMIN_MOTION_PREVIEW_SOURCE_UNSUPPORTED');
        assert.deepEqual(ineligible.puts, []);
    }
    const busy = harness({ pendingS3Key: nextVideoKey });
    await rejectsWith(upload(busy, 0), 409, 'ADMIN_MOTION_PREVIEW_BUSY');
    assert.deepEqual(h.puts, []);
    assert.deepEqual(busy.puts, []);
});

test('a failed replacement keeps the first preview active and public', async () => {
    const h = harness();
    await upload(h, 0);
    const first = h.state.motionPreview.active;
    const enabled = { FINITUDE_MOTION_PREVIEWS_ENABLED: 'true' };

    for (const error of [
        Object.assign(new Error('denied'), { $metadata: { httpStatusCode: 403 } }),
        Object.assign(new Error('timeout'), { name: 'TimeoutError' })
    ]) {
        await assert.rejects(upload(h, h.state.motionPreview.revision, {
            putObject: async () => { throw error; }
        }), MotionPreviewLifecycleError);
        assert.equal(h.state.motionPreview.active.s3Key, first.s3Key);
        assert.equal(publicMotionPreviewForTrack(h.state, enabled)?.s3Key, first.s3Key);
    }
});

test('a definite storage refusal clears the reservation, and an unknown outcome stays reconcilable', async () => {
    const refused = harness();
    await rejectsWith(upload(refused, 0, {
        putObject: async () => { throw Object.assign(new Error('denied'), { $metadata: { httpStatusCode: 403 } }); }
    }), 502, 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED');
    assert.equal(refused.state.motionPreview.pending, null);

    const unknown = harness();
    await rejectsWith(upload(unknown, 0, {
        putObject: async () => { throw Object.assign(new Error('timeout'), { name: 'TimeoutError' }); }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const pending = unknown.state.motionPreview.pending;
    assert.equal(pending.status, 'failed');
    assert.equal(pending.outcomeUnknown, true);
    assert.equal(pending.versionId, null);

    // The next upload resolves the unknown outcome by HEAD on the never-reused key, then proceeds.
    await upload(unknown, unknown.state.motionPreview.revision);
    assert.equal(unknown.state.motionPreview.active.s3Key, unknown.keys[1]);
    assert.equal(unknown.state.motionPreview.pending, null);
});

test('an unknown outcome whose PUT actually landed is deleted by the version HEAD returns', async () => {
    const h = harness();
    await rejectsWith(upload(h, 0, {
        putObject: async (key, received, metadata) => {
            await h.deps.putObject!(key, received, metadata);
            throw Object.assign(new Error('lost response'), { $metadata: { httpStatusCode: 500 } });
        }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const landed = h.keys[0];
    assert.equal(h.objects.has(landed), true);

    await reconcileMotionPreview(trackId, h.deps);

    assert.deepEqual(h.deleted, [{ key: landed, versionId: 'v1' }]);
    assert.equal(h.objects.has(landed), false);
    assert.equal(h.state.motionPreview.pending, null);
});

test('a live upload lease blocks another upload and its recovery', async () => {
    const h = harness({
        motionPreview: {
            active: null, cleanup: null, revision: 1,
            pending: {
                status: 'uploading', s3Key: `motion-preview/${trackId}/64b0000000000000000000dd`, versionId: null,
                outcomeUnknown: true, source: { s3Key: videoKey },
                leaseUntil: new Date('2026-10-18T00:05:00Z'), updatedAt: new Date(), error: null
            }
        }
    });
    await rejectsWith(upload(h, 1), 409, 'ADMIN_MOTION_PREVIEW_BUSY');
    await rejectsWith(reconcileMotionPreview(trackId, h.deps), 409, 'ADMIN_MOTION_PREVIEW_BUSY');
    assert.deepEqual(h.deleted, []);
});

test('a source replaced during upload abandons the preview and deletes its own exact object', async () => {
    const h = harness();
    await rejectsWith(upload(h, 0, {
        putObject: async (key, received, metadata) => {
            const stored = await h.deps.putObject!(key, received, metadata);
            h.state.s3Key = nextVideoKey;
            return stored;
        }
    }), 409, 'ADMIN_MOTION_PREVIEW_SOURCE_CHANGED');
    assert.equal(h.state.motionPreview.active, null);
    assert.equal(h.state.motionPreview.pending, null);
    assert.deepEqual(h.deleted, [{ key: h.keys[0], versionId: 'v1' }]);
    assert.equal(h.objects.size, 0);
});

test('a missing strong ETag abandons the upload instead of publishing an unverifiable preview', async () => {
    const h = harness();
    await rejectsWith(upload(h, 0, {
        putObject: async (key, received, metadata) => {
            const stored = await h.deps.putObject!(key, received, metadata);
            return { VersionId: stored.VersionId };
        }
    }), 502, 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED');
    assert.equal(h.state.motionPreview.active, null);
    assert.equal(h.objects.size, 0);
});

test('a failed old-preview delete keeps the new preview public and blocks the next upload until it drains', async () => {
    const h = harness();
    await upload(h, 0);
    let failDeletes = true;
    const flaky: Partial<MotionPreviewLifecycleDependencies> = {
        deleteObject: async (key, versionId) => {
            if (failDeletes) throw new Error('S3 unavailable');
            await h.deps.deleteObject!(key, versionId);
        }
    };
    const result = await upload(h, h.state.motionPreview.revision, flaky);
    assert.equal(result.cleanupPending, true);
    assert.equal(h.state.motionPreview.active.s3Key, h.keys[1]);
    assert.equal(h.state.motionPreview.cleanup.status, 'deleteFailed');

    await rejectsWith(upload(h, h.state.motionPreview.revision, flaky), 409, 'ADMIN_MOTION_PREVIEW_CLEANUP_PENDING');
    failDeletes = false;
    assert.equal((await reconcileMotionPreview(trackId, { ...h.deps, ...flaky })).cleanupPending, false);
    assert.equal(h.state.motionPreview.cleanup, null);
});

test('retiring a preview made for a replaced Video deletes it, never throws, and leaves deletion alone', async () => {
    const h = harness();
    await upload(h, 0);
    const preview = h.state.motionPreview.active;
    h.state.s3Key = nextVideoKey;

    assert.deepEqual(await retireStaleMotionPreview(trackId, h.deps), { retired: true, cleanupPending: false });
    assert.equal(h.state.motionPreview.active, null);
    assert.deepEqual(h.deleted, [{ key: preview.s3Key, versionId: preview.versionId }]);

    const current = harness();
    await upload(current, 0);
    assert.deepEqual(await retireStaleMotionPreview(trackId, current.deps), { retired: false, cleanupPending: false });

    const deleting = harness();
    await upload(deleting, 0);
    deleting.state.uploadStatus = 'deleting';
    deleting.state.s3Key = nextVideoKey;
    assert.deepEqual(await retireStaleMotionPreview(trackId, deleting.deps), { retired: false, cleanupPending: false });

    assert.deepEqual(await retireStaleMotionPreview(trackId, {
        findTrack: async () => { throw new Error('database unavailable'); }
    }), { retired: false, cleanupPending: true });
});

test('removing a preview deletes its exact version and requires the current revision', async () => {
    const h = harness();
    await upload(h, 0);
    const preview = h.state.motionPreview.active;
    await rejectsWith(removeMotionPreview(trackId, 0, h.deps), 409, 'ADMIN_MOTION_PREVIEW_STALE_REVISION');

    assert.deepEqual(await removeMotionPreview(trackId, h.state.motionPreview.revision, h.deps), { cleanupPending: false });
    assert.equal(h.state.motionPreview.active, null);
    assert.deepEqual(h.deleted, [{ key: preview.s3Key, versionId: preview.versionId }]);
    await rejectsWith(removeMotionPreview(trackId, h.state.motionPreview.revision, h.deps), 404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
});

test('status reports eligibility and a source token without exposing storage keys or versions', async () => {
    const h = harness();
    await upload(h, 0);
    const status = await motionPreviewStatus(trackId, h.deps);

    assert.equal(status.eligible, true);
    assert.equal(status.sourceToken, tokenFor());
    assert.equal(status.active?.current, true);
    const serialized = JSON.stringify(status);
    assert.equal(serialized.includes('motion-preview/'), false);
    assert.equal(serialized.includes('video/'), false);
    assert.equal(serialized.includes('"v1"'), false);

    h.state.s3Key = nextVideoKey;
    assert.equal((await motionPreviewStatus(trackId, h.deps)).active?.current, false);
});

test('stale, mismatched, or ineligible requests are refused before the decode runs', async () => {
    let decodes = 0;
    const counted = (h: Harness) => ({
        validate: async (received: Express.Multer.File, signal?: AbortSignal) => {
            decodes += 1;
            return h.deps.validate!(received, signal);
        }
    });
    const h = harness();
    await rejectsWith(uploadMotionPreview({
        actorId: 'admin-1', mediaTrackId: trackId, file, sourceToken: tokenFor(nextVideoKey), expectedRevision: 0
    }, { ...h.deps, ...counted(h) }), 409, 'ADMIN_MOTION_PREVIEW_SOURCE_CHANGED');
    await rejectsWith(upload(h, 3, counted(h)), 409, 'ADMIN_MOTION_PREVIEW_STALE_REVISION');
    const audio = harness({ mediaType: 'audio', s3Key: `audio/${trackId}/64b0000000000000000000cc` });
    await rejectsWith(upload(audio, 0, counted(audio)), 409, 'ADMIN_MOTION_PREVIEW_SOURCE_UNSUPPORTED');
    const missing = harness();
    await rejectsWith(upload(missing, 0, { ...counted(missing), findTrack: async () => null }), 404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    assert.equal(decodes, 0);
});

test('a promote whose acknowledgement is lost is confirmed by its fence and never deleted while it may be live', async () => {
    // The promote lands but its acknowledgement is lost: the fence misses, so the re-read confirms it.
    const landed = harness();
    const result = await upload(landed, 0, {
        updateTrackWhere: async (id, expected, update) => {
            const applied = await landed.deps.updateTrackWhere!(id, expected, update);
            if ((update as Record<string, any>)['motionPreview.active']) throw new Error('connection reset');
            return applied;
        }
    });
    assert.equal(result.cleanupPending, false);
    assert.equal(landed.state.motionPreview.active.s3Key, landed.keys[0]);
    assert.deepEqual(landed.deleted, []);

    // When the re-read also fails, the possibly live object is kept and recovery is explicit.
    const unconfirmed = harness();
    let promoteFailed = false;
    await rejectsWith(upload(unconfirmed, 0, {
        updateTrackWhere: async (id, expected, update) => {
            const applied = await unconfirmed.deps.updateTrackWhere!(id, expected, update);
            if ((update as Record<string, any>)['motionPreview.active']) {
                promoteFailed = true;
                throw new Error('connection reset');
            }
            return applied;
        },
        findTrack: async () => {
            if (promoteFailed) throw new Error('database unavailable');
            return structuredClone(unconfirmed.state);
        }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    assert.equal(unconfirmed.state.motionPreview.active.s3Key, unconfirmed.keys[0]);
    assert.equal(unconfirmed.objects.has(unconfirmed.keys[0]), true);
    assert.deepEqual(unconfirmed.deleted, []);
});

test('a committed upload or removal reports a failed cleanup read as pending, never as a failure', async () => {
    const h = harness();
    const result = await upload(h, 0, {
        findTrack: async () => {
            if (h.state.motionPreview?.active) throw new Error('database unavailable');
            return structuredClone(h.state);
        }
    });
    assert.equal(result.cleanupPending, true);
    assert.equal(h.state.motionPreview.active.s3Key, h.keys[0]);

    const removal = await removeMotionPreview(trackId, h.state.motionPreview.revision, {
        ...h.deps,
        findTrack: async () => {
            if (h.state.motionPreview.cleanup) throw new Error('database unavailable');
            return structuredClone(h.state);
        }
    });
    assert.deepEqual(removal, { cleanupPending: true });
    assert.equal(h.state.motionPreview.active, null);
    assert.equal(h.state.motionPreview.cleanup.reason, 'removed');
});

test('once MediaTrack deletion begins, preview work refuses, and a racing write leaves its fence untouched', async () => {
    const expiredPending = {
        status: 'failed', s3Key: `motion-preview/${trackId}/64b0000000000000000000dd`, versionId: 'v9',
        outcomeUnknown: false, source: { s3Key: videoKey },
        leaseUntil: new Date('2026-10-17T00:00:00Z'), updatedAt: new Date(), error: 'timeout'
    };
    for (const uploadStatus of ['deleting', 'deleteFailed']) {
        const h = harness();
        await upload(h, 0);
        h.state.uploadStatus = uploadStatus;
        const before = structuredClone(h.state.motionPreview);

        // Deletion owns every preview object: no operation deletes one or changes the record.
        await rejectsWith(removeMotionPreview(trackId, before.revision, h.deps), 409, 'ADMIN_MOTION_PREVIEW_BUSY');
        h.state.motionPreview.cleanup = { status: 'deleteFailed', s3Key: before.active.s3Key, versionId: 'v1', reason: 'replaced' };
        assert.deepEqual(await reconcileMotionPreview(trackId, h.deps), { cleanupPending: true });
        h.state.motionPreview.cleanup = null;
        h.state.motionPreview.pending = structuredClone(expiredPending);
        await rejectsWith(reconcileMotionPreview(trackId, h.deps), 409, 'ADMIN_MOTION_PREVIEW_BUSY');
        h.state.motionPreview.pending = null;
        assert.deepEqual(h.state.motionPreview, before);
        assert.deepEqual(h.deleted, []);

        // Deletion that begins after the read still wins: the guarded write misses.
        const staleRead = { ...h.deps, findTrack: async () => ({ ...structuredClone(h.state), uploadStatus: 'ready' }) };
        await rejectsWith(removeMotionPreview(trackId, before.revision, staleRead), 409, 'ADMIN_MOTION_PREVIEW_STALE_REVISION');
        assert.deepEqual(h.state.motionPreview, before);
        assert.deepEqual(h.deleted, []);
    }
});

test('a bucket without versioning resolves an unknown outcome as the exact null version', async () => {
    const h = harness();
    const unversioned: Partial<MotionPreviewLifecycleDependencies> = {
        putObject: async (key, _received, metadata) => {
            h.puts.push(key);
            h.objects.set(key, { versionId: undefined as unknown as string, etag: '"etag-null"', metadata });
            throw Object.assign(new Error('lost response'), { $metadata: { httpStatusCode: 500 } });
        }
    };
    await rejectsWith(upload(h, 0, unversioned), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const landed = h.keys[0];

    await reconcileMotionPreview(trackId, h.deps);

    assert.deepEqual(h.deleted, [{ key: landed, versionId: null }]);
    assert.equal(h.objects.has(landed), false);
    assert.equal(h.state.motionPreview.pending, null);

    const foreign = harness();
    await rejectsWith(upload(foreign, 0, {
        putObject: async (key, _received) => {
            foreign.objects.set(key, { versionId: 'v1', etag: '"etag-1"', metadata: { trackid: 'someone-else' } });
            throw Object.assign(new Error('lost response'), { $metadata: { httpStatusCode: 500 } });
        }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    await rejectsWith(reconcileMotionPreview(trackId, foreign.deps), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    assert.deepEqual(foreign.deleted, []);
    assert.equal(foreign.state.motionPreview.pending.outcomeUnknown, true);
});

test('recovery fences the pending record before deleting, so a failed delete retries by exact version', async () => {
    const h = harness();
    await rejectsWith(upload(h, 0, {
        putObject: async (key, received, metadata) => {
            await h.deps.putObject!(key, received, metadata);
            throw Object.assign(new Error('lost response'), { $metadata: { httpStatusCode: 500 } });
        }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const landed = h.keys[0];
    const revision = h.state.motionPreview.revision;

    await rejectsWith(reconcileMotionPreview(trackId, {
        ...h.deps,
        deleteObject: async () => { throw new Error('S3 unavailable'); }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const fenced = h.state.motionPreview.pending;
    assert.equal(h.state.motionPreview.revision, revision + 1);
    assert.equal(fenced.status, 'failed');
    assert.equal(fenced.outcomeUnknown, false);
    assert.equal(fenced.versionId, 'v1');

    let heads = 0;
    await reconcileMotionPreview(trackId, {
        ...h.deps,
        headObject: async (key, versionId) => { heads += 1; return h.deps.headObject!(key, versionId); }
    });
    assert.equal(heads, 0);
    assert.deepEqual(h.deleted, [{ key: landed, versionId: 'v1' }]);
    assert.equal(h.state.motionPreview.pending, null);
});

test('every guarded preview write misses once deletion has begun, even after a stale read', async () => {
    const pendingKey = `motion-preview/${trackId}/64b0000000000000000000dd`;
    const staleReadOf = (h: Harness) => ({
        ...h.deps,
        findTrack: async () => ({ ...structuredClone(h.state), uploadStatus: 'ready' })
    });

    // Recovery of an expired pending upload: its fence misses, so nothing is deleted.
    const recovering = harness();
    await upload(recovering, 0);
    recovering.state.motionPreview.pending = {
        status: 'failed', s3Key: pendingKey, versionId: 'v9', outcomeUnknown: false, source: { s3Key: videoKey },
        leaseUntil: new Date('2026-10-17T00:00:00Z'), updatedAt: new Date(), error: 'timeout'
    };
    recovering.state.uploadStatus = 'deleting';
    const pendingBefore = structuredClone(recovering.state.motionPreview);
    await rejectsWith(reconcileMotionPreview(trackId, staleReadOf(recovering)), 409, 'ADMIN_MOTION_PREVIEW_STALE_REVISION');
    assert.deepEqual(recovering.state.motionPreview, pendingBefore);
    assert.deepEqual(recovering.deleted, []);

    // Retirement of a preview made for a replaced Video: its detach misses.
    const retiring = harness();
    await upload(retiring, 0);
    retiring.state.s3Key = nextVideoKey;
    retiring.state.uploadStatus = 'deleteFailed';
    const retireBefore = structuredClone(retiring.state.motionPreview);
    assert.deepEqual(await retireStaleMotionPreview(trackId, {
        ...retiring.deps,
        findTrack: async () => ({ ...structuredClone(retiring.state), uploadStatus: 'ready', mediaType: 'video' })
    }), { retired: false, cleanupPending: false });
    assert.deepEqual(retiring.state.motionPreview, retireBefore);
    assert.deepEqual(retiring.deleted, []);

    // A retained cleanup record keeps its evidence when its clear misses.
    const draining = harness();
    await upload(draining, 0);
    draining.state.motionPreview.cleanup = { status: 'deleteFailed', s3Key: pendingKey, versionId: 'v0', reason: 'replaced' };
    draining.state.uploadStatus = 'deleting';
    await reconcileMotionPreview(trackId, staleReadOf(draining));
    assert.equal(draining.state.motionPreview.cleanup?.s3Key, pendingKey);
});

test('an upload that fails before promotion deletes its own object even when its record changed', async () => {
    const h = harness();
    // The record write lands but its acknowledgement is lost, so the fence then misses.
    await rejectsWith(upload(h, 0, {
        updateTrackWhere: async (id, expected, update) => {
            const applied = await h.deps.updateTrackWhere!(id, expected, update);
            if ((update as Record<string, any>)['motionPreview.pending.outcomeUnknown'] === false
                && !('motionPreview.pending.status' in update)) {
                throw new Error('connection reset');
            }
            return applied;
        }
    }), 503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    const key = h.keys[0];
    // Only this upload could promote its key, so its object goes; the record stays traceable.
    assert.deepEqual(h.deleted, [{ key, versionId: 'v1' }]);
    assert.equal(h.objects.has(key), false);
    assert.equal(h.state.motionPreview.pending.s3Key, key);
    assert.equal(h.state.motionPreview.pending.versionId, 'v1');
    assert.equal(h.state.motionPreview.active, null);
});
